// Pseudo-code: Initialize W as identity, update W with gradient descent
let W = [[1, 0], [0, 1]];
for (let t = 0; t < frames.length; t++) {
  const whitened = whiten(frames[t]);
  const gradient = computeGradient(W, whitened);
  W = updateMatrix(W, gradient, learningRate);
}
